package com.example.campsitelottery

import androidx.compose.ui.test.assertIsDisplayed
import androidx.compose.ui.test.junit4.createComposeRule
import androidx.compose.ui.test.onNodeWithTag
import androidx.compose.ui.test.onNodeWithText
import androidx.compose.ui.test.performClick
import androidx.compose.ui.test.performScrollTo
import androidx.navigation.compose.rememberNavController
import androidx.test.ext.junit.runners.AndroidJUnit4
import org.junit.Rule
import org.junit.Test
import org.junit.runner.RunWith

/**
 * Documentation generated by Claude
 * UI tests for the policy and guidelines popout on the profile screen.
 */
@RunWith(AndroidJUnit4::class)
class ProfilePolicyTest {

    @get:Rule
    val composeRule = createComposeRule()

    private fun showProfile(userState: UserState) {
        val user = User(userId = "device-1", name = "Jane")
        composeRule.setContent {
            ProfileScreen(
                navController = rememberNavController(),
                userState = userState,
                userRepository = InMemoryUserRepository(listOf(user)),
                onUserChanged = {},
                onUserDeleted = {},
            )
        }
    }

    private fun openPolicy() {
        composeRule.onNodeWithTag("toPolicyButton").performScrollTo().performClick()
    }

    @Test
    fun policyButtonOpensAndClosesDialog() {
        showProfile(UserState.Ready(User(userId = "device-1", name = "Jane")))
        composeRule.onNodeWithTag("policyDialog").assertDoesNotExist()

        openPolicy()
        composeRule.onNodeWithTag("policyDialog").assertIsDisplayed()
        composeRule.onNodeWithText(AppPolicyText.sections.first().title).assertIsDisplayed()

        composeRule.onNodeWithTag("closePolicyButton").performClick()
        composeRule.onNodeWithTag("policyDialog").assertDoesNotExist()
    }

    @Test
    fun policyIsAvailableWhileProfileIsLoading() {
        showProfile(UserState.Loading)
        openPolicy()
        composeRule.onNodeWithTag("policyDialog").assertIsDisplayed()
    }
}
